class HeapPriorityQueue:
    def __init__(self):
        self._data = []

    def _upheap(self, j):
        d = self._data
        while j > 0:
            p = (j - 1) // 2
            if d[j] < d[p]:
                d[j], d[p] = d[p], d[j]
                j = p
            else:
                break

    def _downheap(self, j):
        d = self._data
        n = len(d)
        while 2 * j + 1 < n:
            c = 2 * j + 1
            if c + 1 < n and d[c + 1] < d[c]:
                c += 1
            if d[c] < d[j]:
                d[j], d[c] = d[c], d[j]
                j = c
            else:
                break

    def add(self, k, v):
        self._data.append((k, v))
        self._upheap(len(self._data) - 1)

    def min(self):
        return list(self._data[0]) if self._data else None

    def remove_min(self):
        d = self._data
        if not d:
            return None
        d[0], d[-1] = d[-1], d[0]
        item = d.pop()
        self._downheap(0)
        return list(item)

    def size(self):
        return len(self._data)

