def heap_sort(A):
    n = len(A)

    def down(j, size):
        while 2 * j + 1 < size:
            c = 2 * j + 1
            if c + 1 < size and A[c + 1] > A[c]:
                c += 1
            if A[c] > A[j]:
                A[j], A[c] = A[c], A[j]
                j = c
            else:
                break

    for j in range(n // 2 - 1, -1, -1):
        down(j, n)
    for end in range(n - 1, 0, -1):
        A[0], A[end] = A[end], A[0]
        down(0, end)

