import random


def kth_smallest(nums, k):
    S = list(nums)
    while True:
        if len(S) == 1:
            return S[0]
        pivot = random.choice(S)
        L = [x for x in S if x < pivot]
        E = [x for x in S if x == pivot]
        if k <= len(L):
            S = L
        elif k <= len(L) + len(E):
            return pivot
        else:
            k -= len(L) + len(E)
            S = [x for x in S if x > pivot]

