def radix_sort(nums):
    nums = list(nums)
    if not nums:
        return nums
    biggest = max(nums)
    shift = 0
    while (biggest >> shift) > 0:
        buckets = [[] for _ in range(256)]
        for x in nums:
            buckets[(x >> shift) & 255].append(x)
        nums = [x for b in buckets for x in b]
        shift += 8
    return nums

