def topological_order(n, edges):
    adj = [[] for _ in range(n)]
    incount = [0] * n
    for u, v in edges:
        adj[u].append(v)
        incount[v] += 1
    ready = [u for u in range(n) if incount[u] == 0]
    topo = []
    while ready:
        u = ready.pop()
        topo.append(u)
        for v in adj[u]:
            incount[v] -= 1
            if incount[v] == 0:
                ready.append(v)
    return topo if len(topo) == n else []

